export default function Icon({ name, ...props }: IconProps) {
  switch (name) {
    case "user":
      return <User {...props} />;
    case "search":
      return <Search {...props} />;
    case "google-play":
      return <GooglePlay {...props} />;
    case "apple-store":
      return <AppleStore {...props} />;
    case "secure":
      return <Secure {...props} />;
    case "fast":
      return <Fast {...props} />;
    case "dollar":
      return <Dollar {...props} />;
    case "check":
      return <Check {...props} />;
    case "send":
      return <Send {...props} />;
    case "transaction-status":
      return <TransactionStatus {...props} />;
    case "people":
      return <People {...props} />;
    case "linkedin":
      return <LinkedIn {...props} />;
    case "instagram":
      return <Instagram {...props} />;
    case "facebook":
      return <FaceBook {...props} />;
    case "verified":
      return <Verified {...props} />;
    case "google":
      return <Google {...props} />;
    case "camera":
      return <Camera {...props} />;
    case "alt":
      return <Alt {...props} />;
    case "add":
      return <Add {...props} />;
    case "youtube":
      return <Youtube {...props} />;
    case "twitter":
      return <Twitter {...props} />;
    case "dashboard":
      return <DashBoard {...props} />;
    case "payouts":
      return <Payouts {...props} />;
    case "flash":
      return <Flash {...props} />;
    case "settings":
      return <Settings {...props} />;
    case "cash-out":
      return <CashOut {...props} />;
    case "coins":
      return <Coins {...props} />;
    case "inbox-out":
      return <InboxOut {...props} />;
    case "x":
      return <X {...props} />;
    case "more-horizontal":
      return <MoreHorizontal {...props} />;
    default:
      return null;
  }
}
